pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address ownerCaller, address _owner) public {
        vm.assume(ownerCaller != address(0));
        vm.prank(ownerCaller);
        c = new Owned();
        vm.prank(ownerCaller);
        bool ok;
        try c.setOwner(_owner) returns (bool success) { ok = success; } catch { ok = false; }
        if (ok) {
            assertTrue(c.owner() == _owner);
        } else {
            assertTrue(c.owner() == ownerCaller);
        }
    }
}
